3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.util.OwnerIdentities;
8	
9	/**
10	 * Rejects a create-owner request whose whole {@code identityKey} equals an existing owner's. The
11	 * key — normalized telephone, email and householdId joined by {@code '|'} (see
12	 * {@link OwnerIdentities}) — consolidates what were three separate checks (telephone, email and
13	 * household): only an exact full-key match is a duplicate, reported as a 409 (see
14	 * {@link DuplicateIdentityException}).
15	 *
16	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} so the new owner's
17	 * {@code householdId} is already assigned and forms part of the key. Because the telephone is part
18	 * of the key, two members of the same household (same {@code householdId}) with different telephones
19	 * have different keys and are both allowed.
20	 */
21	public class CheckUniqueIdentity {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
24	            throws DuplicateIdentityException {
25	        String identityKey = OwnerIdentities.identityKey(owner);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
28	                continue; // never collide with self (should not yet be persisted, but be safe)
29	            }
30	            if (identityKey.equals(OwnerIdentities.identityKey(existing))) {
31	                throw new DuplicateIdentityException(identityKey);
32	            }
33	        }
34	    }
35	}
